from collections import Counter
def f(g):
    h,w=len(g),len(g[0])
    from collections import deque
    # find separator lines (full rows/cols of a single repeated value forming lines)
    # heuristic: rows/cols consisting entirely of same value c where c appears in full line
    seps=set()
    for r in range(h):
        if len(set(g[r]))==1 and g[r][0]!=max(Counter(x for row in g for x in row)):
            seps.add((r,'row'))
    for c in range(w):
        col=[g[r][c] for r in range(h)]
        if len(set(col))==1 and col[0]!=max(Counter(x for row in g for x in row)):
            seps.add((c,'col'))
    rows=[i for i,_ in seps]; cols=[j for _,j in seps]
    rs=[];prev=-1;
    for r in rows+[h]:
        if r>prev+1: rs.append((prev+1,r))
        prev=r
    cs=[];prev=-1
    for c in cols+[w]:
        if c>prev+1: cs.append((prev+1,c))
        prev=c
    bg=max(Counter(x for row in g for x in row).items(), key=lambda kv:kv[1])[0]
    acc=next(v for v,c in Counter(sum(g,[])).items() if v!=bg and len(seps)>0)[0] if any(v!=bg for v in set(sum(g,[]))) else None
    out=[row[:] for row in g]
    for r0,r1 in rs:
        for c0,c1 in cs:
            blk=[g[i][j] for i in range(r0,r1) for j in range(c0,c1)]
            cnt=Counter(blk)
            acc_cells=[v for v,n in cnt.items() if v!=bg]
            if len(acc_cells)>=1:
                av=acc_cells[0]
                # if mixed accents, pick most frequent accent
                if len(acc_cells)>1:
                    acc_cells.sort(key=lambda v:-cnt[v])
                    av=acc_cells[0]
                for i in range(r0,r1):
                    for j in range(c0,c1):
                        out[i][j]=av
    return out
